function checkForValidUrl(tabId, changeInfo, tab) {
  // If the letter 'g' is found in the tab's URL...
  if (tab.url.match(/likeolda.hu/) || tab.url.match(/eszement.com/) || tab.url.match(/bodzaszorp.com/) || tab.url.match(/video-perc.net/) || tab.url.match(/lopom.hu/) || tab.url.match(/ezkutya.eu/) || tab.url.match(/mindenegyben.info/) || tab.url.match(/ilyennincs.com/) || tab.url.match(/hir27.in/) || tab.url.match(/locitrom.hu/) || tab.url.match(/napi5perc.blogspot.hu/)) {
    // ... show the page action.
    chrome.pageAction.show(tabId);
  }
};

// Listen for any changes to the URL of any tab.
chrome.tabs.onUpdated.addListener(checkForValidUrl);
